suppressMessages({library(dplyr);library(bundeslaendeR)}); options(width=250, dplyr.print_max=300)
d <- "data/state_elections/final/"
u <- readRDS(paste0(d,"state_unharm.rds")); h25 <- readRDS(paste0(d,"state_harm_25.rds")); h21 <- readRDS(paste0(d,"state_harm_21.rds")); h23<-readRDS(paste0(d,"state_harm_23.rds"))
st <- c(BW="08",BY="09",BE="11",BB="12",HB="04",HH="02",HE="06",MV="13",NI="03",NW="05",RP="07",SL="10",SN="14",ST="15",SH="01",TH="16")
bl <- as.data.frame(ltw_elections) %>% mutate(election_date=as.Date(election_date), state_gerda=st[state]) %>% distinct(state_gerda, election_date)
x <- u %>% distinct(state, election_year, election_date) %>% filter(election_year>=1946)
cat("(e) GERDA state-election dates not in bundeslaendeR (<=2021-06 ones):\n"); print(anti_join(x, bl, by=c("state"="state_gerda","election_date")) %>% arrange(state,election_year) %>% as.data.frame())
cat("elections per state-year with >1 distinct date:\n"); print(x %>% count(state,election_year) %>% filter(n>1))
cat("\n(d) vv+iv==nv in harm25 (non BY/HH/HB), |diff|>1 and >1%:\n")
z <- h25 %>% filter(!state %in% c("09","02","04"), !is.na(invalid_votes), !is.na(valid_votes), !is.na(number_voters)) %>% mutate(dd=valid_votes+invalid_votes-number_voters)
cat("rows", nrow(z), " |dd|>2:", sum(abs(z$dd)>2), "\n"); print(z %>% filter(abs(dd)>2) %>% count(state,election_year,sort=TRUE) %>% head(15) %>% as.data.frame())
cat("\n(d2) BY vv ~ 2*nv\n"); print(u %>% filter(state=="09", election_year>=1950) %>% group_by(election_year) %>% summarise(r=sum(valid_votes,na.rm=T)/sum(number_voters,na.rm=T)) %>% as.data.frame())
cat("\n(f) covariates in harm25\n"); print(summary(h25[c("area_ags","population_ags","employees_ags","pop_density_ags")]))
cat("pop_density vs population/area (area unit):\n"); z<-h25 %>% filter(!is.na(area_ags),area_ags>0) %>% mutate(dd=population_ags/area_ags); cat("median pop/area",median(z$dd,na.rm=T),"median pop_density",median(z$pop_density_ags,na.rm=T),"\n"); print(head(z %>% select(ags,ags_name,area_ags,population_ags,pop_density_ags,dd),3))
cat("covariates by year NA share:\n"); print(h25 %>% group_by(election_year) %>% summarise(na_pop=mean(is.na(population_ags)), na_area=mean(is.na(area_ags))) %>% filter(na_pop>0|na_area>0) %>% as.data.frame())
